// Package: Microsoft.SemanticKernel, Microsoft.Extensions.AI

using Microsoft.SemanticKernel;
using Microsoft.Extensions.AI;
using System.ComponentModel;

// --- Reactive Agent ---
public class ReactiveOrderAgent
{
    private readonly IChatClient _chatClient;
    private readonly Kernel _kernel;

    public ReactiveOrderAgent(IChatClient chatClient)
    {
        _chatClient = chatClient;
        _kernel = Kernel.CreateBuilder()
            .AddOpenAIChatCompletion("gpt-4o", new OpenAIClient("your-api-key"))
            .Build();
        _kernel.Plugins.AddFromType<OrderPlugin>();
    }

    public async Task<string> HandleAsync(string userMessage, CancellationToken ct = default)
    {
        // Reactive: single tool call, no planning step
        var response = await _chatClient.GetResponseAsync(
            [new ChatMessage(ChatRole.User, userMessage)],
            tools: _kernel.GetServices<AIFunction>(),
            cancellationToken: ct);

        return response.Text ?? "No response generated.";
    }
}

// --- Planner Agent (modern SK v1.25+ pattern) ---
public class PlannerOrderAgent
{
    private readonly Kernel _kernel;

    public PlannerOrderAgent(Kernel kernel)
    {
        _kernel = kernel;
        _kernel.Plugins.AddFromType<OrderPlugin>();
    }

    public async Task<string> PlanAndExecuteAsync(string goal, CancellationToken ct = default)
    {
        // SequentialPlanner was deprecated in SK v1.19+.
        // Use a function-calling loop with KernelArguments for plan-and-execute.
        var arguments = new KernelArguments();
        arguments["goal"] = goal;

        var prompt = $"""
Goal: {goal}

Available functions:
- OrderPlugin.GetOrderStatus(orderId)
- OrderPlugin.CalculateDiscount(orderId)

Decide which functions to call and in what order.
""";

        var plan = await _kernel.InvokePromptAsync<string>(prompt, arguments, ct);

        // Expected plan output:
        // Step 1: OrderPlugin.GetOrderStatus(orderId: "ABC123")
        // Step 2: OrderPlugin.CalculateDiscount(orderId: "ABC123")
        // Step 3: Compose final answer

        return plan ?? "Plan completed with no output.";
    }
}

public class OrderPlugin
{
    [KernelFunction, Description("Get the current status of an order by ID.")]
    public Task<string> GetOrderStatusAsync(string orderId)
    {
        // Simulated order lookup
        return Task.FromResult(orderId == "ABC123"
            ? "Status: Shipped | Total: $149.99"
            : "Order not found.");
    }

    [KernelFunction, Description("Calculate discount eligibility for an order.")]
    public Task<string> CalculateDiscountAsync(string orderId)
    {
        return Task.FromResult(orderId == "ABC123"
            ? "Discount: 10% loyalty discount applied."
            : "No discount available.");
    }
}
